// theme.js — accès JS aux couleurs de theme.css (source unique des couleurs).
//
// MapLibre, les <canvas> et les SVG générés en JS ne comprennent pas var(--...) : ce module
// lit la valeur réelle de la variable CSS et la renvoie dans un format qu'ils acceptent.
//
//   themeColor("danger")       -> "#ef4444"
//   themeColor("danger", 0.18) -> "rgba(239, 68, 68, 0.18)"
//   themeRgb("accent")         -> "59,130,246"   (pour `--c` : rgba(var(--c), 0.3) en CSS)
//
// Le nom est celui de la variable sans le préfixe « --ox- » : "danger" = --ox-danger.
// Les valeurs sont lues une fois puis mises en cache ; resetThemeCache() les relit
// (utile si les variables changent à l'exécution).
import "./theme.css"; // garantit que les variables existent avant la première lecture

const cache = new Map();
let ctx = null;

// Le canvas normalise n'importe quelle couleur CSS (hex, rgb(), color-mix()...)
// en « #rrggbb » ou « rgba(r, g, b, a) ».
function normalize(raw) {
    if (!ctx) ctx = document.createElement("canvas").getContext("2d");
    ctx.fillStyle = "#000000";
    ctx.fillStyle = raw;
    return ctx.fillStyle;
}

function toRGBA(raw) {
    const n = normalize(raw);
    if (n[0] === "#") {
        return [
            parseInt(n.slice(1, 3), 16),
            parseInt(n.slice(3, 5), 16),
            parseInt(n.slice(5, 7), 16),
            1,
        ];
    }
    const [r, g, b, a = 1] = n.match(/[\d.]+/g).map(Number);
    return [r, g, b, a];
}

function readVar(name) {
    const raw = getComputedStyle(document.documentElement).getPropertyValue(`--ox-${name}`).trim();
    if (!raw) {
        console.warn(`[theme] variable --ox-${name} introuvable : voir theme.css`);
        return null;
    }
    return raw;
}

export function themeColor(name, alpha) {
    const key = `${name}|${alpha ?? ""}`;
    if (cache.has(key)) return cache.get(key);
    const raw = readVar(name);
    let out = "#ff00ff"; // magenta : une couleur manquante se voit tout de suite
    if (raw) {
        const [r, g, b, a] = toRGBA(raw);
        const alphaOut = alpha === undefined ? a : alpha * a;
        out = alphaOut >= 1
            ? normalize(`rgb(${r}, ${g}, ${b})`)
            : `rgba(${r}, ${g}, ${b}, ${+alphaOut.toFixed(3)})`;
    }
    cache.set(key, out);
    return out;
}

export function themeRgb(name) {
    const raw = readVar(name);
    if (!raw) return "255,0,255";
    const [r, g, b] = toRGBA(raw);
    return `${r},${g},${b}`;
}

export function resetThemeCache() {
    cache.clear();
}