// Pastilles de la carte (épingle blanche + disque coloré + picto), partagées par MapView.jsx (images MapLibre)
// et popupUtils.js (marqueur de la mini-carte du panneau) : un seul endroit à modifier.
// À placer dans src/utils/.
import {
    DroneGlyph, AviationGlyph, ExplosionGlyph, MissileGlyph, AirDefenceGlyph,
    NavalGlyph, SmallArmsGlyph, TankGlyph, InfoGlyph, TempleGlyph,
} from "./milGlyphs";

// ── Forme de l'épingle (viewBox 56 x 64, disque centré en (28, 26)) ──
// BADGE_TIP_RADIUS : arrondi de la pointe (en unités du viewBox, hors trait de 6). 0 = pointe vive (trait arrondi seul),
// 4.5 = bien arrondie, 7+ = presque une goutte renversée. La pointe reste à y = 50 (là où l'ancre carte / CSS l'attend).
export const BADGE_TIP_RADIUS = 4.5;
export const BADGE_SHELL_PATH = (() => {
    const cx = 28, cy = 26, r = 15, stroke = 6, tipBottom = 50, rho = BADGE_TIP_RADIUS;
    // Sommet T (virtuel) des deux tangentes au disque, placé pour que le bas du trait arrondi tombe à tipBottom.
    const ty = rho > 0 ? (tipBottom - stroke / 2 - rho - (rho * cy) / r) / (1 - rho / r) : tipBottom - stroke / 2;
    const d = ty - cy;
    const k = Math.sqrt(d * d - r * r);               // longueur de la tangente T -> point de tangence sur le disque
    const sin = r / d, cos = k / d;                   // demi-angle au sommet
    const f = (n) => +n.toFixed(2);
    const qx = (r * k) / d, qy = cy + (r * r) / d;    // points de tangence sur le disque (x relatif à cx)
    if (!(rho > 0)) return `M${cx} ${f(ty)}L${f(cx - qx)} ${f(qy)}A${r} ${r} 0 1 1 ${f(cx + qx)} ${f(qy)}Z`;
    const along = rho * cos / sin;                    // T -> point de tangence du congé sur chaque côté
    const px = (qx / k) * along, py = ty - ((ty - qy) / k) * along; // (x relatif, y) du congé, côté gauche = cx - px
    return `M${f(cx - px)} ${f(py)}L${f(cx - qx)} ${f(qy)}A${r} ${r} 0 1 1 ${f(cx + qx)} ${f(qy)}L${f(cx + px)} ${f(py)}A${rho} ${rho} 0 0 1 ${f(cx - px)} ${f(py)}Z`;
})();

// Pastille par défaut des MIL (weapon_type drone, ou sans correspondance dans MIL_BADGES).
export const MIL_DRONE_BADGE = { id: "tweet-mil-drone-icon", Icon: DroneGlyph };
// Taille du disque coloré et du picto dans la pastille (viewBox 56 x 64, centre en (28, 26)).
// Le disque reste dans l'épingle blanche (rayon 15 + demi-trait 3 = 18) : au-delà de ~16, l'anneau blanc disparaît.
export const BADGE_DISC_RADIUS = 15.5;
export const BADGE_GLYPH_SIZE = 30;

// Pastille des tweets hors MIL (repli : « i »).
export const OTHER_BADGE = { id: "tweet-other-badge-icon", Icon: InfoGlyph };
// Pastille des tweets politiques (conflict_typology = POL) : temple.
export const POL_BADGE = { id: "tweet-pol-badge-icon", Icon: TempleGlyph };

// Pastilles MIL par weapon_type (hors drone, qui est le repli) : même pastille, seul le picto change.
// exact = true : valeur égale (insensible à la casse) ; sinon : la valeur contient `match`.
// Pour ajouter un type : une ligne ici (icône importée ci-dessus), rien d'autre à toucher.
export const MIL_BADGES = [
    { id: "tweet-mil-aviation-icon",         Icon: AviationGlyph,     match: "military aviation", exact: false },
    { id: "tweet-mil-explosives-icon",       Icon: ExplosionGlyph,  match: "explosives",        exact: true },
    { id: "tweet-mil-missiles-icon",         Icon: MissileGlyph,     match: "missiles",          exact: true },
    { id: "tweet-mil-airdefence-icon",       Icon: AirDefenceGlyph,     match: "air defence",       exact: true },
    { id: "tweet-mil-naval-icon",            Icon: NavalGlyph,        match: "naval weapons",     exact: true },
    { id: "tweet-mil-smallarms-icon",        Icon: SmallArmsGlyph,            match: "small arms",        exact: true },
    { id: "tweet-mil-artillery-armour-icon", Icon: TankGlyph, match: "artillery",         exact: false }, // « Artillery & Armour » (tolère « and », « Armor », « &amp; »)
];

export const milBadgeMatches = (b, weaponType) => {
    const v = String(weaponType ?? "").trim().toLowerCase();
    return b.exact ? v === b.match : v.includes(b.match);
};
export const isBadgeMil = (f) => MIL_BADGES.some((b) => milBadgeMatches(b, f.properties?.weapon_type));
// Pastille d'un MIL selon son weapon_type (repli = drone).
export const getMilBadge = (weaponType) => MIL_BADGES.find((b) => milBadgeMatches(b, weaponType)) ?? MIL_DRONE_BADGE;
// Même logique côté MapLibre : expression `case` pour la couche d'icônes (repli = drone).
export const milIconExpression = (fallbackId = MIL_DRONE_BADGE.id) => {
    const wt = ["downcase", ["to-string", ["get", "weapon_type"]]];
    return ["case", ...MIL_BADGES.flatMap((b) => [b.exact ? ["==", wt, b.match] : ["in", b.match, wt], b.id]), fallbackId];
};
// Pastille d'un point hors MIL selon conflict_typology (POL -> temple, sinon « i »).
export const otherIconExpression = () => [
    "case",
    ["==", ["downcase", ["to-string", ["get", "conflict_typology"]]], "pol"], POL_BADGE.id,
    OTHER_BADGE.id,
];